using System;using System.IO;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad]public static class MotionInteractionAuditV06 {
 const string Key="ZTM_MOTION_INTERACTION_V06";static GameView view;static RenderTexture target;static int phase,warm;static double start,at;static PlayerState committed;static StringBuilder report=new StringBuilder();
 static string Root=>Directory.GetParent(Application.dataPath).FullName;static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;
 static MotionInteractionAuditV06(){EditorApplication.update+=Tick;}
 public static string Start(){if(EditorApplication.isPlaying)throw new Exception("Own Editor playing");view=null;phase=warm=0;start=EditorApplication.timeSinceStartup;report.Clear();Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","motion-interaction-v06-save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();return "queued";}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);report.AppendLine("PASS "+label);}
 static bool Same(PlayerState a,PlayerState b){if(a.cash!=b.cash||a.spins!=b.spins||a.freeSpins!=b.freeSpins||a.recoveries!=b.recoveries)return false;for(int i=0;i<8;i++)if(a.fragments[i]!=b.fragments[i]||a.purchased[i]!=b.purchased[i])return false;for(int i=0;i<15;i++)if(a.lastGrid[i]!=b.lastGrid[i])return false;return true;}
 static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying)return;try{if(start==0)start=EditorApplication.timeSinceStartup;if(EditorApplication.timeSinceStartup-start>45)throw new Exception("timeout");if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;target=new RenderTexture(360,640,0,RenderTextureFormat.ARGB32);target.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=target;var s=new PlayerState{cash=100,freeSpins=0};s.fragments[0]=19;s.tutorial.skipped=true;view.SetQaState(s,0);}
 if(++warm<30)return;double now=EditorApplication.timeSinceStartup;
 if(phase==0){if(PixelUi.ReducedMotion){view.QaClick("menu");view.QaClick("motion-toggle");view.QaClick("close-settings");}view.QaPressedSpin();Check(PixelUi.RenderedFaceTravel(UI.Q<Button>("spin"))<1,"press starts at previous raised face");at=now;phase=1;}
 else if(phase==1&&now-at>.13){Check(Mathf.Abs(PixelUi.RenderedFaceTravel(UI.Q<Button>("spin"))-5)<.1,"rendered face reaches five pixel press after easing");view.QaReleaseSpin();at=now;phase=2;}
 else if(phase==2&&now-at>.16){Check(PixelUi.RenderedFaceTravel(UI.Q<Button>("spin"))<.1,"rendered face returns after release");view.QaClick("spin");committed=view.Model.Snapshot;Check(view.QaSpinning&&committed.spins==1,"normal spin commits before cosmetics");Check(committed.fragments[0]>=20&&committed.cash>=60,"committed result meets both purchase criteria");string notice;var disk=new SaveStore(Path.Combine(Environment.GetEnvironmentVariable("ZTM_QA_SAVE_DIR"),"level1-v1.json"),new UnityStateCodec()).Load(out notice);Check(Same(committed,disk),"mid-animation disk reload retains exact committed cash parts grid");view.QaBuy(0);Check(Same(committed,view.Model.Snapshot),"purchase blocked throughout presentation lease");at=now;phase=3;}
 else if(phase==3&&now-at>.12){Check(view.QaReelPhase=="travel","normal motion actually enters travel phase");for(int i=0;i<30;i++)view.QaClick("spin");Check(Same(committed,view.Model.Snapshot),"thirty repeated STOP taps grant no extra roll or resources");at=now;phase=4;}
 else if(phase==4&&!view.QaSpinning){Check(now-at<.4,"STOP finishes presentation promptly");Check(Same(committed,view.Model.Snapshot),"skip preserves exact result");for(int i=0;i<30;i++)view.QaClick("spin");Check(Same(committed,view.Model.Snapshot),"post-stop same-frame taps respect cooldown");view.QaClick("buy-0");view.QaBuy(0);Check(view.Model.PurchasedCount==1&&view.Model.Snapshot.cash==committed.cash-60,"purchase after lease debits once");at=now;phase=5;}
 else if(phase==5&&now-at>.6){view.QaClick("menu");var before=view.Model.Snapshot;view.QaClick("motion-toggle");Check(PixelUi.ReducedMotion,"calm preference toggles");Check(new PresentationPreferences(Environment.GetEnvironmentVariable("ZTM_QA_SAVE_DIR")).ReducedMotion,"calm preference survives reload");Check(Same(before,view.Model.Snapshot),"preference changes no game resources");var modal=UI.Q<VisualElement>("settings");Check(modal.worldBound.yMin>=0&&modal.worldBound.yMax<=UI.worldBound.yMax,"expanded menu remains on compact portrait");view.QaClick("close-settings");view.QaClick("spin");Check(view.QaReelPhase!="travel"||UI.Q<VisualElement>("reel-strip-0")==null,"calm mode creates no moving strips");at=now;phase=6;}
 else if(phase==6&&!view.QaSpinning){Check(now-at<.45,"calm spin resolves within short presentation");view.QaClick("menu");view.QaClick("motion-toggle");view.QaClick("close-settings");at=now;phase=70;}
 else if(phase==70&&now-at>.25){int rolls=view.Model.Snapshot.spins;view.QaClick("spin");committed=view.Model.Snapshot;Check(view.QaSpinning&&committed.spins==rolls+1,"queued menu test starts an actual fresh spin");view.QaClick("menu");at=now;phase=7;}
 else if(phase==7&&!view.QaSpinning){Check(now-at<.4,"same-frame menu/skip request is retained before coroutine first frame");Check(UI.Q<VisualElement>("settings").resolvedStyle.display==DisplayStyle.Flex,"menu request during spin skips and opens after lease");Check(Same(committed,view.Model.Snapshot),"queued menu preserves committed spin");report.AppendLine("SOURCE actual Editor frames; synthetic callbacks; private save; no physical input");Finish();}
 }catch(Exception e){report.AppendLine("FAIL "+e);Debug.LogException(e);Finish();}}
 static void Finish(){SessionState.SetBool(Key,false);File.WriteAllText(Path.Combine(Root,"Evidence","motion-interaction-v06-checks.txt"),report.ToString());if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);target=null;}EditorApplication.ExitPlaymode();}
 }
}